const storage = {
  get(key, fallback) { try { const value = localStorage.getItem(key); return value ? JSON.parse(value) : fallback } catch { return fallback } },
  set(key, value) { localStorage.setItem(key, JSON.stringify(value)) }
}
const api = async (url, options = {}) => {
  const response = await fetch(url, { credentials: 'include', headers: { 'Content-Type': 'application/json', ...options.headers }, ...options })
  const data = await response.json().catch(() => ({}))
  if (!response.ok) { const error = new Error(data.error || 'Không thể kết nối máy chủ.'); error.status = response.status; throw error }
  return data
}
function useLibrary() {
  const [subjects, setSubjects] = useState(() => storage.get('subjects', seedSubjects))
  const [documents, setDocuments] = useState(() => storage.get('documents', seedDocuments))
  const [loading, setLoading] = useState(isSupabaseConfigured)
  const [error, setError] = useState('')
  useEffect(() => { if (!supabase) storage.set('subjects', subjects) }, [subjects])
  useEffect(() => { if (!supabase) storage.set('documents', documents) }, [documents])
  useEffect(() => {
    if (!supabase) return undefined
    let cancelled = false
    const load = async () => {
      const [subjectResult, documentResult] = await Promise.all([
        supabase.from('subjects').select('*').order('name'),
        supabase.from('documents').select('*').order('uploaded_at', { ascending: false })
      ])
      if (cancelled) return
      if (subjectResult.error || documentResult.error) setError(subjectResult.error?.message || documentResult.error?.message || 'Không thể tải dữ liệu từ Supabase.')
      else { setSubjects(subjectResult.data || []); setDocuments(documentResult.data || []) }
      setLoading(false)
    }
    load()
    return () => { cancelled = true }
  }, [])
  const isUuid = (value) => typeof value === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(value)
  const saveSubjects = async (next) => {
    setSubjects(next)
    if (!supabase) return
    try {
      const previousIds = new Set(subjects.map(subject => subject.id))
      const nextIds = new Set(next.filter(subject => isUuid(subject.id)).map(subject => subject.id))
      const removedIds = subjects.filter(subject => isUuid(subject.id) && !nextIds.has(subject.id)).map(subject => subject.id)
      if (removedIds.length) {
        const { error: removeError } = await supabase.from('subjects').delete().in('id', removedIds)
        if (removeError) throw removeError
      }
      for (const subject of next) {
        const payload = { name: subject.name, code: subject.code, description: subject.description || '', icon: subject.icon || 'book', is_active: subject.is_active !== false }
        if (isUuid(subject.id) && previousIds.has(subject.id)) {
          const { error: updateError } = await supabase.from('subjects').update(payload).eq('id', subject.id)
          if (updateError) throw updateError
        } else if (!isUuid(subject.id)) {
          const { data, error: insertError } = await supabase.from('subjects').insert(payload).select().single()
          if (insertError) throw insertError
          if (!data) throw new Error('Supabase không trả về môn học vừa tạo.')
          setSubjects(current => current.map(item => item.id === subject.id ? data : item))
        }
      }
    } catch (saveError) { setError(`Không thể lưu môn học vào Supabase: ${saveError.message}`) }
  }
  const saveDocuments = async (next) => {
    setDocuments(next)
    if (!supabase) return
    try {
      const previousIds = new Set(documents.map(document => document.id))
      const nextIds = new Set(next.filter(document => isUuid(document.id)).map(document => document.id))
      const removed = documents.filter(document => isUuid(document.id) && !nextIds.has(document.id)).map(document => document.id)
      if (removed.length) {
        const { error: removeError } = await supabase.from('documents').delete().in('id', removed)
        if (removeError) throw removeError
      }
      for (const document of next) {
        const payload = { subject_id: document.subject_id, title: document.title, topic: document.topic || '', description: document.description || '', file_url: document.file_url || null, file_path: document.file_path || null, file_name: document.file_name, file_type: document.file_type, file_size: Number(document.file_size) || 0, study_date: document.study_date || null, uploaded_at: document.uploaded_at || new Date().toISOString() }
        if (previousIds.has(document.id)) {
          const { error: updateError } = await supabase.from('documents').update(payload).eq('id', document.id)
          if (updateError) throw updateError
        } else {
          const { data, error: insertError } = await supabase.from('documents').insert(payload).select().single()
          if (insertError) throw insertError
          if (!data) throw new Error('Supabase không trả về tài liệu vừa tạo.')
          setDocuments(current => current.map(item => item.id === document.id ? data : item))
        }
      }
    } catch (saveError) { setError(`Không thể lưu tài liệu vào Supabase: ${saveError.message}`) }
  }
  return { subjects, setSubjects: saveSubjects, documents, setDocuments: saveDocuments, loading, error }
}
const formatDate = (value) => {
  if (!value) return '—'
  const date = /^\d{4}-\d{2}-\d{2}$/.test(value)
    ? new Date(`${value}T00:00:00`)
    : new Date(value)
  return Number.isNaN(date.getTime()) ? '—' : new Intl.DateTimeFormat('vi-VN').format(date)
}
const subjectName = (subjects, id) => subjects.find((item) => item.id === id)?.name || 'Môn chưa phân loại'
function fileIcon(type) {
  const props = { size: 21, strokeWidth: 1.8 }
  if (type === 'PDF') return <FileText {...props} className="file-icon pdf" />
  if (['DOC', 'DOCX', 'TXT'].includes(type)) return <FileType2 {...props} className="file-icon word" />
  if (['XLS', 'XLSX'].includes(type)) return <FileSpreadsheet {...props} className="file-icon excel" />
  if (['PPT', 'PPTX'].includes(type)) return <FileText {...props} className="file-icon ppt" />
  if (['PNG', 'JPG', 'JPEG'].includes(type)) return <FileImage {...props} className="file-icon image" />
  if (type === 'ZIP') return <FileArchive {...props} className="file-icon zip" />
  return <FileText {...props} className="file-icon" />
}
function App() {
  const library = useLibrary()
  const [auth, setAuth] = useState({ loading: true, user: null })
  useEffect(() => {
    if (supabase) {
      const resolveUser = async (session) => {
        if (!session?.user) return setAuth({ loading: false, user: null })
        const { data: profile } = await supabase.from('profiles').select('*').eq('id', session.user.id).maybeSingle()
        const canAccessAdmin = profile?.is_active && ['admin', 'super_admin'].includes(profile.role)
        setAuth({ loading: false, user: canAccessAdmin ? { ...session.user, ...profile } : null })
      }
      supabase.auth.getSession().then(({ data }) => resolveUser(data.session))
      const { data: listener } = supabase.auth.onAuthStateChange((_event, session) => resolveUser(session))
      return () => listener.subscription.unsubscribe()
    }
    api('/api/auth/me').then(data => setAuth({ loading: false, user: data.user })).catch(() => setAuth({ loading: false, user: null }))
  }, [])
  if (auth.loading || library.loading) return <div className="app-loading">Đang tải dữ liệu...</div>
  return <><Routes>
    <Route path="/" element={<PublicLayout auth={auth} setAuth={setAuth} />}><Route index element={<Home {...library} />} /><Route path="subjects" element={<Subjects {...library} />} /><Route path="subjects/:subjectId" element={<SubjectDocuments {...library} />} /><Route path="documents/:documentId" element={<DocumentDetail {...library} />} /><Route path="search" element={<SearchPage {...library} />} /></Route>
    <Route path="/admin/login" element={<SecureAdminLogin setAuth={setAuth} />} />
    <Route path="/admin/*" element={<SecureAdminGuard auth={auth}><SecureAdminLayout auth={auth} setAuth={setAuth} library={library} /></SecureAdminGuard>} />
    <Route path="*" element={<Navigate to="/" replace />} />
  </Routes>{library.error && <div className="data-warning" role="alert">{library.error} Dữ liệu hiện tại vẫn được giữ để bạn có thể tiếp tục sử dụng.</div>}</>
}
function PublicLayout({ auth, setAuth }) {
  const [menuOpen, setMenuOpen] = useState(false)
  const navigate = useNavigate()
  const logout = async () => { if (supabase) await supabase.auth.signOut(); else await api('/api/auth/logout', { method: 'POST' }); setAuth({ loading: false, user: null }); navigate('/') }
  return <div className="app-shell"><header className="site-header"><Link to="/" className="brand"><span className="brand-mark"><Library size={18} /></span><span>KHO TÀI LIỆU <b>LỚP</b></span></Link><button className="icon-button mobile-menu" onClick={() => setMenuOpen(!menuOpen)} aria-label="Mở menu"><Menu size={22} /></button><nav className={menuOpen ? 'main-nav open' : 'main-nav'}><NavLink to="/" end onClick={() => setMenuOpen(false)}>Trang chủ</NavLink><NavLink to="/subjects" onClick={() => setMenuOpen(false)}>Môn học</NavLink><NavLink to="/search" onClick={() => setMenuOpen(false)}>Tìm tài liệu</NavLink>{auth.user && <><NavLink to="/admin" onClick={() => setMenuOpen(false)}>Quản trị</NavLink><button className="nav-logout" onClick={logout}><LogOut size={15} /> Đăng xuất</button></>}</nav></header><Outlet /><footer className="site-footer"><div className="footer-inner"><div className="brand"><span className="brand-mark"><Library size={18} /></span><span>KHO TÀI LIỆU <b>LỚP</b></span></div><span>Nơi cả lớp học cùng tiến bộ.</span></div></footer></div>
}
function SearchBox({ initial = '', compact = false }) { const navigate = useNavigate(); const [term, setTerm] = useState(initial); return <form className={compact ? 'search-box compact' : 'search-box'} onSubmit={(event) => { event.preventDefault(); navigate(`/search?q=${encodeURIComponent(term)}`) }}><Search size={20} /><input value={term} onChange={(e) => setTerm(e.target.value)} placeholder="Tìm kiếm tài liệu, môn học, chủ đề..." aria-label="Tìm kiếm" />{term && <button type="button" className="clear-search" onClick={() => setTerm('')}><X size={16} /></button>}<button className="search-submit">Tìm kiếm</button></form> }
function Home({ subjects, documents }) { const latest = [...documents].sort((a,b) => b.uploaded_at.localeCompare(a.uploaded_at)).slice(0, 5); return <main><section className="hero"><div className="hero-copy"><span className="eyebrow"><Sparkles size={15} /> KHÔNG GIAN HỌC TẬP CỦA LỚP</span><h1>Học đúng thứ bạn cần,<br /><em>ngay khi cần.</em></h1><p>Tìm kiếm bài giảng, giáo trình, đề bài và tài liệu học tập một cách nhanh chóng.</p><SearchBox /><div className="hero-meta"><span><Check size={16} /> Tài liệu được sắp xếp rõ ràng</span><span><Check size={16} /> Tải xuống nhanh chóng</span></div></div><div className="hero-visual"><div className="visual-grid"></div><div className="floating-note note-one"><BookOpen size={18} /><span><b>126+</b><small>Tài liệu hữu ích</small></span></div><div className="floating-note note-two"><span className="pulse-dot"></span><span><b>Luôn cập nhật</b><small>Cho mỗi buổi học</small></span></div><div className="hero-book"><div className="book-spine"></div><div className="book-page"><span>CLASS<br /><b>NOTES</b></span><small>HỌC CÙNG NHAU</small></div></div></div></section><section className="section subject-section"><div className="section-heading"><div><span className="eyebrow muted">KHÁM PHÁ</span><h2>Môn học của lớp</h2></div><Link to="/subjects" className="text-link">Xem tất cả <ArrowRight size={16} /></Link></div><div className="subject-grid">{subjects.filter(s => s.is_active).slice(0, 6).map((subject) => <SubjectCard key={subject.id} subject={subject} count={documents.filter(d => d.subject_id === subject.id).length} />)}</div></section><section className="section latest-section"><div className="section-heading"><div><span className="eyebrow muted">MỚI CẬP NHẬT</span><h2>Tài liệu mới nhất</h2></div><Link to="/search" className="text-link">Xem tất cả <ArrowRight size={16} /></Link></div><div className="document-list">{latest.map((document) => <DocumentRow key={document.id} document={document} subject={subjectName(subjects, document.subject_id)} />)}</div></section><ProjectCorner /></main> }
function ProjectCorner() { const projects = [{ name: 'BananaCoach', description: 'Một sản phẩm cá nhân đang được xây dựng để hỗ trợ việc học và phát triển kỹ năng.', icon: '🍌', url: '#' }]; return <section className="section project-corner"><div className="section-heading"><div><span className="eyebrow muted">DỰ ÁN CÁ NHÂN</span><h2>Góc dự án</h2><p className="project-intro">Một vài dự án và sản phẩm mình đang xây dựng.</p></div></div><div className="project-grid">{projects.map(project => <article className="project-card" key={project.name}><div className="project-icon" aria-hidden="true">{project.icon}</div><div className="project-card-content"><h3>{project.name}</h3><p>{project.description}</p><a className="outline-button small" href={project.url}>Xem dự án <ArrowUpRight size={14} /></a></div></article>)}</div></section> }
function SubjectCard({ subject, count }) { return <Link to={`/subjects/${subject.id}`} className="subject-card"><div className="subject-icon">{subject.icon}</div><div className="subject-card-body"><span className="subject-code">{subject.code}</span><h3>{subject.name}</h3><p>{count} tài liệu</p></div><span className="card-arrow"><ArrowUpRight /></span></Link> }
function DocumentRow({ document, subject, admin = false, onDelete }) { return <div className="document-row"><div className="document-file-icon">{fileIcon(document.file_type)}</div><div className="document-info"><Link to={`/documents/${document.id}`}><h3>{document.title}</h3></Link><div className="document-meta"><span>{subject}</span><span className="dot-separator">{document.topic}</span><span className="dot-separator">{document.file_type} · {document.file_size}</span></div></div><div className="document-date"><span>Ngày học</span><b>{formatDate(document.study_date)}</b></div><div className="document-actions">{admin ? <><Link className="icon-button" title="Xem" to={`/documents/${document.id}`}><Eye size={17} /></Link><button className="icon-button danger" title="Xóa" onClick={() => onDelete?.(document.id)}><Trash2 size={17} /></button></> : <><Link className="outline-button small" to={`/documents/${document.id}`}>Xem</Link><button className="download-button" onClick={() => alert('Bản demo: file sẽ được tải xuống khi kết nối storage thật.')}><Download size={16} /> Tải</button></>}</div></div> }
function Subjects({ subjects, documents }) { const [query, setQuery] = useState(''); const filtered = subjects.filter(s => s.is_active && `${s.name} ${s.code}`.toLowerCase().includes(query.toLowerCase())); return <main className="page-container"><div className="page-intro"><div><span className="eyebrow muted">THƯ VIỆN</span><h1>Môn học</h1><p>Chọn một môn để xem toàn bộ tài liệu được chia sẻ trong lớp.</p></div><div className="inline-search"><Search size={18} /><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Tìm môn học..." /></div></div><div className="subject-grid large">{filtered.map(subject => <SubjectCard key={subject.id} subject={subject} count={documents.filter(d => d.subject_id === subject.id).length} />)}</div>{!filtered.length && <EmptyState icon={<BookOpen />} title="Không tìm thấy môn học" text="Thử tìm bằng tên hoặc mã môn khác." />}</main> }
function SubjectDocuments({ subjects, documents }) { const { subjectId } = useParams(); const subject = subjects.find(s => s.id === subjectId); const [query, setQuery] = useState(''); const [type, setType] = useState('Tất cả'); const filtered = documents.filter(d => d.subject_id === subjectId && `${d.title} ${d.topic} ${d.description}`.toLowerCase().includes(query.toLowerCase()) && (type === 'Tất cả' || d.file_type === type)); if (!subject) return <Navigate to="/subjects" />; return <main className="page-container"><Link to="/subjects" className="back-link"><ArrowLeft size={16} /> Môn học</Link><div className="subject-hero"><div className="subject-icon large-icon">{subject.icon}</div><div><span className="subject-code">{subject.code}</span><h1>{subject.name}</h1><p>{subject.description}</p></div><span className="count-badge">{documents.filter(d => d.subject_id === subjectId).length} tài liệu</span></div><div className="filter-bar"><div className="inline-search grow"><Search size={18} /><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Tìm trong môn này..." /></div><div className="select-wrap"><Filter size={16} /><select value={type} onChange={e => setType(e.target.value)}><option>Tất cả</option>{['PDF','DOCX','PPTX','XLSX','ZIP','JPG','TXT'].map(item => <option key={item}>{item}</option>)}</select><ChevronDown size={15} /></div></div><div className="document-list">{filtered.map(document => <DocumentRow key={document.id} document={document} subject={subject.name} />)}</div>{!filtered.length && <EmptyState icon={<FolderOpen />} title="Môn này chưa có tài liệu phù hợp" text="Hãy thử đổi từ khóa hoặc bộ lọc." />}</main> }
function SearchPage({ subjects, documents }) { const params = new URLSearchParams(useLocation().search); const [query, setQuery] = useState(params.get('q') || ''); const results = documents.filter(d => `${d.title} ${d.topic} ${d.description} ${subjectName(subjects, d.subject_id)}`.toLowerCase().includes(query.toLowerCase())); return <main className="page-container"><div className="search-page-head"><span className="eyebrow muted">TÌM KIẾM TOÀN KHO</span><h1>Tìm tài liệu</h1><p>Tìm theo tên tài liệu, môn học, bài học hoặc mô tả.</p><div className="search-inline-form"><SearchBox initial={query} compact /></div></div>{query && <div className="result-caption">{results.length} kết quả cho <b>“{query}”</b></div>}<div className="document-list">{results.map(document => <DocumentRow key={document.id} document={document} subject={subjectName(subjects, document.subject_id)} />)}</div>{!results.length && <EmptyState icon={<Search />} title="Không tìm thấy tài liệu" text="Thử tìm kiếm bằng từ khóa khác." />}</main> }
function DocumentDetail({ subjects, documents }) { const { documentId } = useParams(); const document = documents.find(d => d.id === documentId); if (!document) return <Navigate to="/" />; const subject = subjectName(subjects, document.subject_id); return <main className="page-container detail-page"><Link to={`/subjects/${document.subject_id}`} className="back-link"><ArrowLeft size={16} /> Quay lại {subject}</Link><div className="detail-layout"><article className="detail-card"><div className="detail-icon">{fileIcon(document.file_type)}</div><span className="file-pill">{document.file_type}</span><h1>{document.title}</h1><p className="detail-description">{document.description}</p><div className="detail-grid"><div><span>Môn học</span><b>{subject}</b></div><div><span>Bài / chủ đề</span><b>{document.topic}</b></div><div><span>Ngày học</span><b>{formatDate(document.study_date)}</b></div><div><span>Ngày đăng</span><b>{formatDate(document.uploaded_at)}</b></div><div><span>Dung lượng</span><b>{document.file_size}</b></div><div><span>Tên file</span><b>{document.file_name}</b></div></div><div className="detail-buttons"><button className="primary-button" onClick={() => alert('Bản demo: file sẽ được tải xuống khi kết nối storage thật.')}><Download size={18} /> Tải tài liệu</button><Link to={`/subjects/${document.subject_id}`} className="outline-button">Xem các tài liệu khác</Link></div></article><aside className="preview-panel"><div className="preview-top"><span>THÔNG TIN FILE</span><MoreHorizontal size={18} /></div><div className="preview-file">{fileIcon(document.file_type)}<div><b>{document.file_name}</b><span>{document.file_type} · {document.file_size}</span></div></div><div className="preview-placeholder"><FileText size={34} /><span>Xem trước không khả dụng</span><small>Tải file về máy để mở tài liệu.</small></div></aside></div></main> }
function EmptyState({ icon, title, text }) { return <div className="empty-state">{icon}<h2>{title}</h2><p>{text}</p></div> }

function SecureAdminGuard({ children, auth }) { return auth.user ? children : <Navigate to="/admin/login" replace /> }
function SecureAdminLogin({ setAuth }) {
  const navigate = useNavigate(); const [error, setError] = useState(''); const [form, setForm] = useState({ email: '', password: '' })
  const login = async (event) => { event.preventDefault(); setError(''); try { if (supabase) { const { data, error: loginError } = await supabase.auth.signInWithPassword(form); if (loginError) throw loginError; setAuth({ loading: false, user: data.user }); navigate('/admin') } else { const data = await api('/api/auth/login', { method: 'POST', body: JSON.stringify(form) }); setAuth({ loading: false, user: data.user }); navigate('/admin') } } catch (loginError) { setError('Email hoặc mật khẩu không đúng.') } }
  return <div className="login-page"><Link to="/" className="brand login-brand"><span className="brand-mark"><Library size={18} /></span><span>KHO TÀI LIỆU <b>LỚP</b></span></Link><div className="login-card"><div className="login-icon"><ShieldCheck /></div><span className="eyebrow muted">KHU VỰC QUẢN TRỊ</span><h1>Chào mừng trở lại</h1><p>Đăng nhập để quản lý kho tài liệu của lớp.</p><form onSubmit={login}><label>Email quản trị<input type="email" required value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} /></label><label>Mật khẩu<input type="password" required value={form.password} onChange={e => setForm({ ...form, password: e.target.value })} /></label>{error && <div className="form-error">{error}</div>}<button className="primary-button full"><LogIn size={17} /> Đăng nhập</button></form></div><Link to="/" className="back-link login-back"><ArrowLeft size={16} /> Về trang chủ</Link></div>
}
function SecureAdminLayout({ auth, setAuth, library }) {
  const [sidebarOpen, setSidebarOpen] = useState(false); const navigate = useNavigate(); const isSuperAdmin = auth.user.role === 'super_admin'
  const logout = async () => { if (supabase) await supabase.auth.signOut(); else await api('/api/auth/logout', { method: 'POST' }); setAuth({ loading: false, user: null }); navigate('/admin/login') }
  return <div className="admin-shell"><aside className={sidebarOpen ? 'admin-sidebar open' : 'admin-sidebar'}><div className="sidebar-brand"><span className="brand-mark"><Library size={18} /></span><b>KHO LỚP</b><button className="icon-button sidebar-close" onClick={() => setSidebarOpen(false)}><X size={19} /></button></div><div className="sidebar-label">KHÔNG GIAN QUẢN TRỊ</div><nav className="sidebar-nav"><AdminNav to="/admin" icon={<LayoutDashboard size={18} />} label="Tổng quan" end onClick={() => setSidebarOpen(false)} /><AdminNav to="/admin/subjects" icon={<BookOpen size={18} />} label="Môn học" onClick={() => setSidebarOpen(false)} /><AdminNav to="/admin/documents" icon={<FileText size={18} />} label="Tài liệu" onClick={() => setSidebarOpen(false)} /><AdminNav to="/admin/documents/new" icon={<Plus size={18} />} label="Thêm tài liệu" onClick={() => setSidebarOpen(false)} />{isSuperAdmin && <AdminNav to="/admin/users" icon={<CircleUserRound size={18} />} label="Quản lý tài khoản" onClick={() => setSidebarOpen(false)} />}</nav><div className="sidebar-bottom"><button onClick={() => navigate('/')}><Eye size={17} /> Xem website</button><button onClick={logout}><LogOut size={17} /> Đăng xuất</button></div></aside><div className="admin-content"><header className="admin-header"><button className="icon-button admin-menu" onClick={() => setSidebarOpen(true)}><Menu /></button><div><span className="admin-header-kicker">THỨ SÁU, 11 THÁNG 9, 2026</span><h2>Không gian quản trị</h2></div><div className="admin-user"><span className="avatar">{auth.user.full_name?.[0] || 'A'}</span><span><b>{auth.user.full_name}</b><small>{auth.user.role === 'super_admin' ? 'Super Admin' : 'Admin'}</small></span><Settings size={18} /></div></header><div className="admin-main"><Routes><Route index element={<AdminOverview {...library} />} /><Route path="subjects" element={<AdminSubjects {...library} />} /><Route path="documents" element={<AdminDocuments {...library} />} /><Route path="documents/new" element={<AdminDocumentForm {...library} />} /><Route path="users" element={isSuperAdmin ? <AdminUsers currentUser={auth.user} /> : <ForbiddenPage />} /></Routes></div></div></div>
}
function ForbiddenPage() { return <div className="empty-state"><ShieldCheck size={35} /><h2>403 Forbidden</h2><p>Bạn không có quyền truy cập khu vực này.</p></div> }
function AdminUsers({ currentUser }) {
  const [users, setUsers] = useState([]); const [logs, setLogs] = useState([]); const [showForm, setShowForm] = useState(false); const [error, setError] = useState(''); const [form, setForm] = useState({ full_name: '', email: '' })
  const load = async () => { try { if (supabase) { const [{ data: profileData, error: profileError }, { data: logData, error: logError }] = await Promise.all([supabase.from('profiles').select('*').order('created_at'), supabase.from('activity_logs').select('*').order('created_at', { ascending: false }).limit(50)]); if (profileError || logError) throw profileError || logError; setUsers(profileData || []); setLogs(logData || []) } else { const data = await api('/api/admin/users'); setUsers(data.users); setLogs(data.activity_logs || []) } } catch (loadError) { setError(loadError.message) } }
  useEffect(() => { load() }, [])
  const create = async (event) => { event.preventDefault(); setError(''); try { if (supabase) { const session = (await supabase.auth.getSession()).data.session; await api('/api/admin/invite', { method: 'POST', headers: { Authorization: `Bearer ${session.access_token}` }, body: JSON.stringify({ email: form.email, full_name: form.full_name }) }) } else await api('/api/admin/users', { method: 'POST', body: JSON.stringify({ ...form, password: 'temporary-password-not-used', role: 'admin' }) }); setForm({ full_name: '', email: '' }); setShowForm(false); load() } catch (createError) { setError(createError.message) } }
  const toggle = async (user) => { try { if (supabase) { const { error: updateError } = await supabase.from('profiles').update({ is_active: !user.is_active }).eq('id', user.id); if (updateError) throw updateError } else await api(`/api/admin/users/${user.id}`, { method: 'PATCH', body: JSON.stringify({ is_active: !user.is_active }) }); load() } catch (toggleError) { setError(toggleError.message) } }
  const remove = async (user) => { if (!window.confirm(`Xóa tài khoản ${user.email}?`)) return; try { if (supabase) { const { error: deleteError } = await supabase.from('profiles').delete().eq('id', user.id); if (deleteError) throw deleteError } else await api(`/api/admin/users/${user.id}`, { method: 'DELETE' }); load() } catch (removeError) { setError(removeError.message) } }
  return <><AdminPageHead eyebrow="BẢO MẬT" title="Quản lý tài khoản" text={`Đăng nhập với vai trò ${currentUser.role === 'super_admin' ? 'Super Admin' : 'Admin'}.`} action={<button className="primary-button" onClick={() => setShowForm(!showForm)}><Plus size={18} /> Cấp tài khoản admin</button>} />{showForm && <form className="form-panel user-form" onSubmit={create}><div className="form-grid"><label>Họ tên<input required value={form.full_name} onChange={e => setForm({ ...form, full_name: e.target.value })} /></label><label>Email invitation<input required type="email" value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} /></label><label>Role<select value="admin" disabled><option value="admin">Admin</option></select></label></div><p className="form-help">Admin sẽ nhận email và tự đặt mật khẩu. Không tạo được super_admin từ giao diện.</p>{error && <div className="form-error">{error}</div>}<div className="form-actions"><button type="button" className="outline-button" onClick={() => setShowForm(false)}>Hủy</button><button className="primary-button"><Check size={17} /> Gửi lời mời</button></div></form>}{error && !showForm && <div className="form-error">{error}</div>}<div className="admin-table users-table"><div className="table-head"><span>Email</span><span>Họ tên</span><span>Role</span><span>Trạng thái</span><span>Ngày tạo</span><span>Actions</span></div>{users.map(user => <div className="table-row" key={user.id}><div className="table-subject"><span className="mini-subject-icon"><CircleUserRound size={15} /></span><div><b>{user.email}</b><small>{user.id === currentUser.id ? 'Tài khoản hiện tại' : ''}</small></div></div><span>{user.full_name}</span><span className="code-tag">{user.role}</span><span className={user.is_active ? 'status active' : 'status hidden'}>{user.is_active ? 'Hoạt động' : 'Đã khóa'}</span><span>{formatDate(user.created_at.slice(0, 10))}</span><div className="row-actions">{user.role === 'admin' && <><button className="icon-button" title={user.is_active ? 'Khóa' : 'Mở khóa'} onClick={() => toggle(user)}>{user.is_active ? <ShieldCheck size={16} /> : <Check size={16} />}</button><button className="icon-button danger" title="Xóa" onClick={() => remove(user)}><Trash2 size={16} /></button></>}</div></div>)}</div><section className="admin-panel activity-panel"><div className="panel-heading"><div><span className="eyebrow muted">AUDIT LOG</span><h2>Hoạt động gần đây</h2></div></div>{logs.slice(0, 8).map(log => <div className="activity-item" key={log.id}><span>{formatDate(log.created_at.slice(0, 10))}</span><b>{log.actor_name || 'Hệ thống'}</b><p>{log.action} · {log.target}</p></div>)}</section></>
}
function AdminGuard({ children }) { return localStorage.getItem('admin_session') === 'true' ? children : <Navigate to="/admin/login" replace /> }
function AdminLogin() { const navigate = useNavigate(); const [error, setError] = useState(''); const [form, setForm] = useState({ email: '', password: '' }); const login = e => { e.preventDefault(); if (form.email === 'admin@lop.local' && form.password === 'admin123') { localStorage.setItem('admin_session', 'true'); navigate('/admin') } else setError('Email hoặc mật khẩu chưa đúng.') }; return <div className="login-page"><Link to="/" className="brand login-brand"><span className="brand-mark"><Library size={18} /></span><span>KHO TÀI LIỆU <b>LỚP</b></span></Link><div className="login-card"><div className="login-icon"><ShieldCheck /></div><span className="eyebrow muted">KHU VỰC QUẢN TRỊ</span><h1>Chào mừng trở lại</h1><p>Đăng nhập để quản lý kho tài liệu của lớp.</p><form onSubmit={login}><label>Email quản trị<input type="email" required value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} placeholder="admin@lop.local" /></label><label>Mật khẩu<input type="password" required value={form.password} onChange={e => setForm({ ...form, password: e.target.value })} placeholder="••••••••" /></label>{error && <div className="form-error">{error}</div>}<button className="primary-button full"><LogIn size={17} /> Đăng nhập</button></form><div className="demo-hint">Demo: admin@lop.local / admin123</div></div><Link to="/" className="back-link login-back"><ArrowLeft size={16} /> Về trang chủ</Link></div> }
function AdminLayout({ library }) { const [sidebarOpen, setSidebarOpen] = useState(false); const navigate = useNavigate(); const logout = () => { localStorage.removeItem('admin_session'); navigate('/admin/login') }; return <div className="admin-shell"><aside className={sidebarOpen ? 'admin-sidebar open' : 'admin-sidebar'}><div className="sidebar-brand"><span className="brand-mark"><Library size={18} /></span><b>KHO LỚP</b><button className="icon-button sidebar-close" onClick={() => setSidebarOpen(false)}><X size={19} /></button></div><div className="sidebar-label">KHÔNG GIAN QUẢN TRỊ</div><nav className="sidebar-nav"><AdminNav to="/admin" icon={<LayoutDashboard size={18} />} label="Tổng quan" end onClick={() => setSidebarOpen(false)} /><AdminNav to="/admin/subjects" icon={<BookOpen size={18} />} label="Môn học" onClick={() => setSidebarOpen(false)} /><AdminNav to="/admin/documents" icon={<FileText size={18} />} label="Tài liệu" onClick={() => setSidebarOpen(false)} /><AdminNav to="/admin/documents/new" icon={<Plus size={18} />} label="Thêm tài liệu" onClick={() => setSidebarOpen(false)} /></nav><div className="sidebar-bottom"><button onClick={() => navigate('/')}><Eye size={17} /> Xem website</button><button onClick={logout}><LogOut size={17} /> Đăng xuất</button></div></aside><div className="admin-content"><header className="admin-header"><button className="icon-button admin-menu" onClick={() => setSidebarOpen(true)}><Menu /></button><div><span className="admin-header-kicker">THỨ SÁU, 11 THÁNG 9, 2026</span><h2>Không gian quản trị</h2></div><div className="admin-user"><span className="avatar">A</span><span><b>Quản trị viên</b><small>admin@lop.local</small></span><Settings size={18} /></div></header><div className="admin-main"><Routes><Route index element={<AdminOverview {...library} />} /><Route path="subjects" element={<AdminSubjects {...library} />} /><Route path="documents" element={<AdminDocuments {...library} />} /><Route path="documents/new" element={<AdminDocumentForm {...library} />} /></Routes></div></div></div> }
function AdminNav({ to, icon, label, end, onClick }) { return <NavLink to={to} end={end} onClick={onClick}>{icon}<span>{label}</span></NavLink> }
function AdminOverview({ subjects, documents }) { const latest = [...documents].sort((a,b) => b.uploaded_at.localeCompare(a.uploaded_at)).slice(0, 4); return <><div className="admin-title-row"><div><span className="eyebrow muted">TỔNG QUAN</span><h1>Bảng điều khiển</h1><p>Theo dõi và quản lý nội dung học tập của lớp.</p></div><Link className="primary-button" to="/admin/documents/new"><Plus size={18} /> Thêm tài liệu</Link></div><div className="stats-grid"><StatCard icon={<BookOpen />} label="Tổng môn học" value={subjects.filter(s => s.is_active).length} tone="blue" /><StatCard icon={<FileText />} label="Tổng tài liệu" value={documents.length} tone="orange" /><StatCard icon={<CalendarDays />} label="Tài liệu tháng này" value={documents.filter(d => d.uploaded_at.startsWith('2026-09')).length} tone="green" /><StatCard icon={<Upload />} label="Tài liệu hôm nay" value={documents.filter(d => d.uploaded_at === '2026-09-11').length} tone="purple" /></div><div className="admin-columns"><section className="admin-panel"><div className="panel-heading"><div><span className="eyebrow muted">MỚI NHẤT</span><h2>Tài liệu vừa cập nhật</h2></div><Link to="/admin/documents" className="text-link">Xem tất cả <ArrowRight size={15} /></Link></div><div className="admin-doc-list">{latest.map(doc => <DocumentRow key={doc.id} document={doc} subject={subjectName(subjects, doc.subject_id)} admin />)}</div></section><section className="admin-panel"><div className="panel-heading"><div><span className="eyebrow muted">PHÂN BỔ</span><h2>Môn học nổi bật</h2></div></div><div className="popular-list">{subjects.slice(0, 5).map((subject, i) => { const count = documents.filter(d => d.subject_id === subject.id).length; return <div className="popular-item" key={subject.id}><span className="rank">0{i + 1}</span><span className="mini-subject-icon">{subject.icon}</span><div><b>{subject.name}</b><small>{count} tài liệu</small></div><span className="bar" style={{ '--width': `${Math.max(12, count / Math.max(documents.length, 1) * 100)}%` }}></span></div> })}</div></section></div></> }
function StatCard({ icon, label, value, tone }) { return <div className={`stat-card ${tone}`}><div className="stat-icon">{icon}</div><div><span>{label}</span><strong>{value}</strong></div><span className="stat-trend">+12%</span></div> }
function AdminSubjects({ subjects, setSubjects, documents }) { const navigate = useNavigate(); const [showForm, setShowForm] = useState(false); const [editing, setEditing] = useState(null); const [query, setQuery] = useState(''); const filtered = subjects.filter(s => s.name.toLowerCase().includes(query.toLowerCase()) || s.code.toLowerCase().includes(query.toLowerCase())); const save = form => { const id = editing?.id || `${form.name.toLowerCase().replace(/[^a-z0-9]+/g, '-')}-${Date.now()}`; const item = { ...form, id, updated_at: new Date().toISOString().slice(0,10), created_at: editing?.created_at || new Date().toISOString().slice(0,10) }; setSubjects(editing ? subjects.map(s => s.id === editing.id ? item : s) : [...subjects, item]); setShowForm(false); setEditing(null) }; const remove = subject => { const count = documents.filter(d => d.subject_id === subject.id).length; if (window.confirm(count ? `Môn học này đang có ${count} tài liệu. Bạn có chắc chắn muốn ẩn môn?` : 'Bạn có chắc chắn muốn xóa môn học này?')) setSubjects(subjects.map(s => s.id === subject.id ? { ...s, is_active: false } : s)) }; return <><AdminPageHead eyebrow="NỘI DUNG" title="Môn học" text="Tổ chức các môn học và không gian tài liệu của lớp." action={<button className="primary-button" onClick={() => { setEditing(null); setShowForm(true) }}><Plus size={18} /> Thêm môn học</button>} /><div className="toolbar"><div className="inline-search"><Search size={17} /><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Tìm môn học..." /></div><span className="toolbar-count">{filtered.length} môn học</span></div>{showForm && <SubjectForm initial={editing} onSave={save} onClose={() => { setShowForm(false); setEditing(null) }} />}<div className="admin-table"><div className="table-head"><span>Môn học</span><span>Mã môn</span><span>Tài liệu</span><span>Trạng thái</span><span>Cập nhật</span><span></span></div>{filtered.map(subject => <div className="table-row" key={subject.id}><div className="table-subject"><span className="mini-subject-icon">{subject.icon}</span><div><b>{subject.name}</b><small>{subject.description}</small></div></div><span className="code-tag">{subject.code}</span><span>{documents.filter(d => d.subject_id === subject.id).length}</span><span className={subject.is_active ? 'status active' : 'status hidden'}>{subject.is_active ? 'Đang hiển thị' : 'Đã ẩn'}</span><span>{formatDate(subject.updated_at)}</span><div className="row-actions"><button className="icon-button" title="Sửa" onClick={() => { setEditing(subject); setShowForm(true) }}><Pencil size={16} /></button><button className="icon-button danger" title="Ẩn" onClick={() => remove(subject)}><Trash2 size={16} /></button></div></div>)}</div></> }
function AdminPageHead({ eyebrow, title, text, action }) { return <div className="admin-title-row"><div><span className="eyebrow muted">{eyebrow}</span><h1>{title}</h1><p>{text}</p></div>{action}</div> }
function SubjectForm({ initial, onSave, onClose }) { const [form, setForm] = useState(initial || { name: '', code: '', icon: '✦', description: '', is_active: true }); return <div className="form-panel"><div className="panel-heading"><h2>{initial ? 'Chỉnh sửa môn học' : 'Thêm môn học mới'}</h2><button className="icon-button" onClick={onClose}><X size={18} /></button></div><div className="form-grid"><label>Tên môn học<input required value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} placeholder="Ví dụ: Lập trình C" /></label><label>Mã môn<input required value={form.code} onChange={e => setForm({ ...form, code: e.target.value.toUpperCase() })} placeholder="CS101" /></label><label>Icon<input value={form.icon} onChange={e => setForm({ ...form, icon: e.target.value })} placeholder="⌘" /></label><label className="wide">Mô tả<textarea value={form.description} onChange={e => setForm({ ...form, description: e.target.value })} placeholder="Mô tả ngắn về môn học..." /></label></div><div className="form-actions"><button className="outline-button" onClick={onClose}>Hủy</button><button className="primary-button" onClick={() => form.name && form.code && onSave(form)}><Check size={17} /> Lưu môn học</button></div></div> }
function AdminDocuments({ subjects, documents, setDocuments }) { const [query, setQuery] = useState(''); const [type, setType] = useState('Tất cả'); const filtered = documents.filter(d => `${d.title} ${d.topic}`.toLowerCase().includes(query.toLowerCase()) && (type === 'Tất cả' || d.file_type === type)); const remove = id => { if (window.confirm('Bạn có chắc chắn muốn xóa tài liệu này?')) setDocuments(documents.filter(d => d.id !== id)) }; return <><AdminPageHead eyebrow="NỘI DUNG" title="Tài liệu" text="Tìm kiếm, kiểm tra và quản lý tất cả tài liệu trong kho." action={<Link className="primary-button" to="/admin/documents/new"><Plus size={18} /> Thêm tài liệu</Link>} /><div className="toolbar"><div className="inline-search grow"><Search size={17} /><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Tìm tên tài liệu hoặc chủ đề..." /></div><div className="select-wrap"><SlidersHorizontal size={16} /><select value={type} onChange={e => setType(e.target.value)}><option>Tất cả</option>{['PDF','DOCX','PPTX','XLSX','ZIP'].map(item => <option key={item}>{item}</option>)}</select><ChevronDown size={15} /></div><span className="toolbar-count">{filtered.length} tài liệu</span></div><div className="admin-table documents-table"><div className="table-head"><span>Tài liệu</span><span>Môn học</span><span>Ngày học</span><span>Loại</span><span>Dung lượng</span><span></span></div>{filtered.map(doc => <div className="table-row" key={doc.id}><div className="table-subject"><div className="document-file-icon small-file">{fileIcon(doc.file_type)}</div><div><Link to={`/documents/${doc.id}`}><b>{doc.title}</b></Link><small>{doc.topic}</small></div></div><span>{subjectName(subjects, doc.subject_id)}</span><span>{formatDate(doc.study_date)}</span><span className="file-type-label">{doc.file_type}</span><span>{doc.file_size}</span><div className="row-actions"><Link className="icon-button" title="Xem" to={`/documents/${doc.id}`}><Eye size={16} /></Link><button className="icon-button danger" title="Xóa" onClick={() => remove(doc.id)}><Trash2 size={16} /></button></div></div>)}</div>{!filtered.length && <EmptyState icon={<FileText />} title="Chưa có tài liệu phù hợp" text="Thử đổi từ khóa hoặc bộ lọc." />}</> }
function AdminDocumentForm({ subjects, documents, setDocuments }) { const navigate = useNavigate(); const [form, setForm] = useState({ subject_id: subjects[0]?.id || '', title: '', topic: '', study_date: '2026-09-11', uploaded_at: '2026-09-11', description: '', file_type: 'PDF', file_name: '', file_size: '', file_path: '', file_url: '' }); const [error, setError] = useState(''); const submit = e => { e.preventDefault(); if (!form.title || !form.file_name) return setError('Vui lòng nhập tên tài liệu và chọn file.'); const newDoc = { ...form, id: crypto.randomUUID(), created_at: new Date().toISOString(), uploaded_at: new Date().toISOString() }; setDocuments([newDoc, ...documents]); navigate('/admin/documents') }; const onFile = async e => { const file = e.target.files?.[0]; if (!file) return; const ext = file.name.split('.').pop().toUpperCase(); const allowed = ['PDF','DOC','DOCX','PPT','PPTX','XLS','XLSX','ZIP','PNG','JPG','JPEG','TXT']; if (!allowed.includes(ext)) return setError('File không được hỗ trợ. Vui lòng chọn PDF, DOCX, PPTX, XLSX, ZIP, ảnh hoặc TXT.'); if (file.size > 20 * 1024 * 1024) return setError('File quá lớn. Giới hạn tối đa là 20 MB.'); setError(''); const metadata = { file_name: file.name, file_type: ext, file_size: file.size }; if (supabase) { const path = `${crypto.randomUUID()}-${file.name.replace(/[^a-zA-Z0-9._-]/g, '-')}`; const { error: uploadError } = await supabase.storage.from('documents').upload(path, file, { contentType: file.type, upsert: false }); if (uploadError) return setError(`Upload thất bại: ${uploadError.message}`); metadata.file_path = path; metadata.file_url = supabase.storage.from('documents').getPublicUrl(path).data.publicUrl } setForm({ ...form, ...metadata }) }; return <><AdminPageHead eyebrow="NỘI DUNG" title="Thêm tài liệu" text="Bổ sung tài liệu mới vào đúng môn học để cả lớp dễ tìm thấy." /><form className="document-form" onSubmit={submit}><div className="form-panel"><div className="form-section-title"><span className="step-number">01</span><div><h2>Thông tin tài liệu</h2><p>Nhập các thông tin giúp mọi người tìm đúng tài liệu.</p></div></div><div className="form-grid"><label>Môn học<select value={form.subject_id} onChange={e => setForm({ ...form, subject_id: e.target.value })}>{subjects.filter(s => s.is_active).map(s => <option key={s.id} value={s.id}>{s.name}</option>)}</select></label><label>Tên tài liệu<input required value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} placeholder="Ví dụ: Bài 03 - Con trỏ trong C" /></label><label>Bài / chủ đề<input value={form.topic} onChange={e => setForm({ ...form, topic: e.target.value })} placeholder="Ví dụ: Con trỏ" /></label><label>Ngày học<input type="date" value={form.study_date} onChange={e => setForm({ ...form, study_date: e.target.value })} /></label><label>Ngày đăng<input type="date" value={form.uploaded_at} onChange={e => setForm({ ...form, uploaded_at: e.target.value })} /></label><label className="wide">Mô tả<textarea value={form.description} onChange={e => setForm({ ...form, description: e.target.value })} placeholder="Một vài dòng mô tả nội dung..." /></label></div></div><div className="form-panel"><div className="form-section-title"><span className="step-number">02</span><div><h2>File tài liệu</h2><p>Hỗ trợ PDF, Word, PowerPoint, Excel, ZIP, ảnh và TXT. Tối đa 20 MB.</p></div></div><label className="dropzone">{form.file_name ? <><div className="uploaded-file">{fileIcon(form.file_type)}<div><b>{form.file_name}</b><span>{form.file_type} · {form.file_size}</span></div><Check className="upload-check" size={20} /></div><small>Chọn file khác</small></> : <><Upload size={28} /><b>Kéo file vào đây hoặc chọn file</b><small>PDF, DOCX, PPTX, XLSX, ZIP, PNG, JPG, TXT</small></>}<input type="file" onChange={onFile} accept=".pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.zip,.png,.jpg,.jpeg,.txt" /></label>{error && <div className="form-error">{error}</div>}<div className="form-actions"><button type="button" className="outline-button" onClick={() => navigate('/admin/documents')}>Hủy</button><button className="primary-button" type="submit"><Upload size={17} /> Upload tài liệu</button></div></div></form></> }

createRoot(document.getElementById('root')).render(<BrowserRouter><App /></BrowserRouter>)
